const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../lib/stream-transfer.cjs');
const { Readable, Writable }=require('node:stream');
function bounded(promise) {
  let timer;
  return Promise.race([promise,new Promise((_,reject)=>{
    timer=setTimeout(()=>reject(new Error('transfer did not settle')),1500);
  })]).finally(()=>clearTimeout(timer));
}
test('wait until destination finalization completes', async () => {
  const chunks=[]; let finalized=false;
  const source=Readable.from([Buffer.from('north'),Buffer.from('-south')]);
  const destination=new Writable({
    write(chunk,encoding,callback) { chunks.push(chunk);setImmediate(callback); },
    final(callback) { setImmediate(()=>{finalized=true;callback();}); }
  });
  try {
    await bounded(app.transfer(source,destination));
    assert.equal(finalized,true); assert.equal(destination.writableFinished,true);
    assert.equal(Buffer.concat(chunks).toString(),'north-south');
  } finally { source.destroy(); destination.destroy(); }
});
test('source failure rejects and destroys the unfinished destination', async () => {
  const error=new Error('source disconnected');
  const source=new Readable({read() { this.destroy(error); }});
  const destination=new Writable({write(c,e,cb) { cb(); }});
  source.on('error',()=>{}); destination.on('error',()=>{});
  try {
    await assert.rejects(bounded(app.transfer(source,destination)),e=>e===error);
    assert.equal(source.destroyed,true); assert.equal(destination.destroyed,true);
  } finally { source.destroy(); destination.destroy(); }
});
test('destination failure rejects and destroys the unfinished source', async () => {
  const error=new Error('destination unavailable'); let sent=false;
  const source=new Readable({read() { if(!sent){sent=true;this.push('chunk');} }});
  const destination=new Writable({write(c,e,cb) { cb(error); }});
  source.on('error',()=>{}); destination.on('error',()=>{});
  try {
    await assert.rejects(bounded(app.transfer(source,destination)),e=>e===error);
    assert.equal(source.destroyed,true); assert.equal(destination.destroyed,true);
  } finally { source.destroy(); destination.destroy(); }
});
test('abort signal rejects the pending pipeline and destroys both streams', async () => {
  const source=new Readable({read() {}});
  const destination=new Writable({write(c,e,cb) { cb(); }});
  const controller=new AbortController();
  source.on('error',()=>{}); destination.on('error',()=>{});
  try {
    const check=assert.rejects(bounded(app.transfer(source,destination,controller.signal)),e=>e.name==='AbortError');
    controller.abort(); await check;
    assert.equal(source.destroyed,true); assert.equal(destination.destroyed,true);
  } finally { source.destroy(); destination.destroy(); }
});

